import React, { useState } from "react";

const LeadForm = ({ onAdd }) => {
  const [form, setForm] = useState({ name: "", email: "", phone: "" });

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.name || !form.email) return alert("Vui lòng nhập đủ thông tin!");
    onAdd(form);
    setForm({ name: "", email: "", phone: "" });
  };

  return (
    <form
      onSubmit={handleSubmit}
      className="flex gap-3 mb-4 bg-white p-4 rounded-lg shadow"
    >
      <input
        name="name"
        value={form.name}
        onChange={handleChange}
        placeholder="Tên khách hàng"
        className="border p-2 rounded w-1/4 focus:ring-2 focus:ring-blue-300"
      />
      <input
        name="email"
        type="email"
        value={form.email}
        onChange={handleChange}
        placeholder="Email"
        className="border p-2 rounded w-1/4 focus:ring-2 focus:ring-blue-300"
      />
      <input
        name="phone"
        value={form.phone}
        onChange={handleChange}
        placeholder="Số điện thoại"
        className="border p-2 rounded w-1/4 focus:ring-2 focus:ring-blue-300"
      />
      <button
        type="submit"
        className="bg-blue-600 text-white px-4 rounded hover:bg-blue-700 transition"
      >
        ➕ Thêm
      </button>
    </form>
  );
};

export default LeadForm;
